-- 0117_repair_consult_57c8bbc5.sql
-- One-off data repair, not a schema change.
--
-- The console rendered the full 88-question doctor intake while the server
-- re-derived a 85-question, sex-filtered list and zipped the answers by index.
-- For a male client the three "Female — " questions vanished on the server side
-- only, so every answer from that point on was filed against a question three
-- places later: the vitals narrative ended up under "Labs — HbA1c", which then
-- produced the flag "HbA1c 78%".
--
-- The cause is fixed in code (the question text now travels with its answer).
-- This restores the one consultation that was captured before that fix. The
-- three answers typed into the female-specific questions are dropped, and the
-- last three answers were never received by the server, so they stay blank.
--
-- Verify first:
--   select answers -> 88 from consultations where id = '57c8bbc5-a640-4a8d-b4dc-2a8f3bea7b46';

update consultations
   set answers = '[["Primary goal / reason for visit", "Fat loss. Wants to reduce body fat and improve energy; desk job, gradual weight gain over the last 3 years."], ["Prenatal — maternal health during pregnancy (diet, stress, toxins/medications)", "Mother reported an uneventful pregnancy. Home-cooked vegetarian-leaning diet, no smoking or alcohol, no significant illness or medication."], ["Prenatal — mode of delivery (vaginal / C-section)", "Normal vaginal delivery at a district hospital."], ["Prenatal — birth weight & gestational age (term/preterm)", "Approx. 3.0 kg, born at term (~39 weeks)."], ["Prenatal — birth complications (NICU, infections, jaundice)", "None reported. No NICU stay, no neonatal jaundice or infection."], ["Early childhood (0–5) — feeding practices (breastfeeding / formula / weaning)", "Exclusively breastfed ~6 months, weaning onto rice/dal and mashed vegetables from 6 months."], ["Early childhood — growth milestones (physical, mental, emotional)", "Milestones reported age-appropriate — sat, walked and spoke within normal range."], ["Early childhood — early illnesses (recurrent infections, hospitalizations)", "Usual childhood coughs and colds only. No hospitalisation."], ["Early childhood — environmental exposures (smoke, mold, pollution)", "Non-smoking household. Semi-urban home, adequate ventilation, no known mold exposure."], ["Early childhood — family stressors / instability", "Stable family environment. No major stressors recalled."], ["School age (6–12) — dietary habits (lunchbox, snacking, junk food)", "Home-cooked lunchbox most days; frequent bakery snacks and sweetened drinks after school."], ["School age — physical activity & sports", "Active — daily outdoor play, school-level football until about age 12."], ["School age — academic stress or bullying", "Ordinary exam stress. No bullying reported."], ["School age — sleep pattern & quality", "Roughly 9 hours nightly, described as sound and unbroken."], ["School age — childhood diseases (asthma, allergies, infections)", "No asthma, eczema or recurrent infections reported."], ["Adolescence (13–18) — growth & puberty milestones (menarche, height spurts)", "Puberty at the expected age; growth spurt around 14, no delay noted."], ["Adolescence — eating habits (junk food, dieting)", "Increased fast food and fried snacks, irregular meal timing, skipped breakfast often."], ["Adolescence — sleep duration & disturbances", "Around 6-7 hours on school nights, later bedtimes with phone use."], ["Adolescence — physical activity (sports, gym, sedentary)", "Reduced after age 15 — moved from regular sport to largely sedentary."], ["Adolescence — stress levels (academic, peer)", "Moderate to high around board exams. Managed without professional support."], ["Adolescence — smoking / alcohol / recreational-drug exposure", "No smoking, alcohol or recreational drug use during adolescence."], ["Early adulthood (19–30) — dietary patterns (balanced vs processed)", "Largely home-cooked but carbohydrate-heavy (rice twice daily), low vegetable and protein intake, frequent eating out at weekends."], ["Early adulthood — physical activity routine", "Intermittent — occasional gym membership, never sustained beyond 2-3 months."], ["Early adulthood — sleep quality & recovery", "6-7 hours, variable. Reports waking unrefreshed on workdays."], ["Early adulthood — stressors (work, relationships, financial)", "Work deadlines and long commute; some financial pressure in the mid-20s."], ["Early adulthood — environmental toxins (workplace chemicals, pollution)", "No occupational chemical exposure. Urban traffic pollution on daily commute."], ["Early adulthood — specify toxin & duration of exposure", "Not applicable — no specific toxin identified."], ["Early adulthood — medical conditions diagnosed", "None diagnosed during this period."], ["Current — medical conditions (name, since when, treatment type & duration)", "None. No diagnosed chronic illness to date."], ["Current — impaired fasti